{"results": [{"id": "hp_doc_23ebfcbb6dabd92f316770559053bcbad418822168835a44b0de5f078ac7dd26", "title": "Tom Molineaux", "text": "Tom \"The Moor\" Molineaux (1784 – 4 August 1818) was an African-American bare-knuckle boxer. He spent much of his career in Great Britain and Ireland, where he had some notable successes.", "score": 24.7705}, {"id": "hp_doc_41c638e3dec330ff700681152c71384b6d427559b55397b85db762f2f30d2d88", "title": "Black Ajax", "text": "Black Ajax is a historical novel by George MacDonald Fraser based on the career of Tom Molineaux.", "score": 22.5944}, {"id": "hp_doc_588f74f8a3251d83939c5ec7f3e727618c0acc62b812a7451b1d6dc2ec05e44a", "title": "Mr. Baseball", "text": "Mr. Baseball is a 1992 American sports comedy film directed by Fred Schepisi, starring Tom Selleck, Ken Takakura, Dennis Haysbert, and Aya Takanashi. It depicts a tumultuous season in the career of veteran New York Yankees first baseman Jack Elliot, who is traded to the Chunichi Dragons of the Japanese Central League during Spring Training, and forced to contend with overwhelming expectations and cultural differences during the Dragons' run at the pennant.", "score": 7.8749}], "remaining_searches": 1}
